 * In-flight request deduplication.
 *
 * Wraps an async function of one string key so that concurrent calls with
 * the same key share a single in-flight promise. The promise is cleared as
 * soon as it settles, so a later call refetches. Rejections propagate to
 * every waiter and are never cached.
 */

export type KeyedAsync<T> = (key: string) => Promise<T>;

export interface Deduped<T> {
  /** The deduplicated function. */
  (key: string): Promise<T>;
  /** Number of keys with a currently in-flight promise (useful for tests/metrics). */
  readonly inFlight: number;
}

export function dedupe<T>(fn: KeyedAsync<T>): Deduped<T> {
  const inflight = new Map<string, Promise<T>>();

  const wrapped = ((key: string): Promise<T> => {
    const existing = inflight.get(key);
    if (existing) return existing;

    const p = fn(key).finally(() => {
      // Clear on settle (fulfill or reject) so the next call refetches.
      if (inflight.get(key) === p) inflight.delete(key);
    });

    inflight.set(key, p);
    return p;
  }) as Deduped<T>;

  Object.defineProperty(wrapped, "inFlight", {
    get: () => inflight.size,
  });

  return wrapped;
}

/**
 * Tiny read-through layer built on top of dedupe:
 * a fetch stub standing in for a real backend call.
 */
export interface User {
  id: string;
  name: string;
}

export type FetchUser = (id: string) => Promise<User>;

export function makeFetchUser(
  impl: FetchUser = async (id) => ({ id, name: `user-${id}` }),
): FetchUser {
  return impl;
}

export function makeGetUser(fetchUser: FetchUser): (id: string) => Promise<User> {
  return dedupe(fetchUser);
}
