import { dedupe, makeGetUser, type User } from "../src/index";

describe("dedupe", () => {
  it("shares one underlying call for two concurrent same-key calls", async () => {
    const fn = vi.fn(async (key: string) => ({ key }));
    const d = dedupe(fn);

    const [a, b] = await Promise.all([d("k"), d("k")]);

    expect(fn).toHaveBeenCalledTimes(1);
    expect(a).toBe(b); // same object identity
  });

  it("propagates rejection to every waiter and does not cache it; retry calls fn again", async () => {
    let attempts = 0;
    const fn = vi.fn(async (key: string) => {
      attempts++;
      if (attempts === 1) throw new Error(`boom-${key}`);
      return { key, ok: true };
    });
    const d = dedupe(fn);

    const [r1, r2] = await Promise.allSettled([d("k"), d("k")]);
    expect(r1.status).toBe("rejected");
    expect(r2.status).toBe("rejected");
    if (r1.status === "rejected") expect((r1.reason as Error).message).toBe("boom-k");
    expect(fn).toHaveBeenCalledTimes(1); // both waiters shared one call

    const retried = await d("k"); // later call refetches
    expect(retried).toEqual({ key: "k", ok: true });
    expect(fn).toHaveBeenCalledTimes(2);
  });

  it("interleaved different keys never interfere", async () => {
    const fn = vi.fn(async (key: string) => ({ key }));
    const d = dedupe(fn);

    const results = await Promise.all([d("a"), d("b"), d("a"), d("c"), d("b")]);

    expect(fn).toHaveBeenCalledTimes(3); // distinct keys only
    const [ra, rb, ra2, rc, rb2] = results;
    expect(ra).toBe(ra2);
    expect(rb).toBe(rb2);
    expect(rc).toEqual({ key: "c" });
  });

  it("stress: 100 mixed calls invoke fn once per distinct key", async () => {
    const keys = ["k1", "k2", "k3", "k4"];
    const fn = vi.fn(async (key: string) => ({ key }));
    const d = dedupe(fn);

    const calls: Promise<unknown>[] = [];
    for (let i = 0; i < 100; i++) {
      calls.push(d(keys[i % keys.length]));
    }
    await Promise.all(calls);

    expect(fn).toHaveBeenCalledTimes(keys.length);
  });
});

describe("getUser (read-through layer)", () => {
  it("fetches through the stub once for concurrent identical ids", async () => {
    const fetchUser = vi.fn(async (id: string): Promise<User> => ({
      id,
      name: `user-${id}`,
    }));
    const getUser = makeGetUser(fetchUser);

    const [u1, u2] = await Promise.all([getUser("u1"), getUser("u1")]);

    expect(fetchUser).toHaveBeenCalledTimes(1);
    expect(u1).toBe(u2);
    expect(u1).toEqual({ id: "u1", name: "user-u1" });
  });
});
